"use client";

import { chakra } from "@chakra-ui/react"

export const PlaygroundTable = chakra("table", {
  base: {
    width: "full",
    marginBottom: "32px",
    borderCollapse: "collapse",
    "& td:not(.chakra-table__cell)": {
      paddingRight: "8",
      paddingBottom: "8",
    },
    "& th:not(.chakra-table__column-header)": {
      fontSize: "sm",
      color: "fg.muted",
    },
    "& thead td:not(.chakra-table__cell)": {
      fontSize: "sm",
      color: "fg.muted",
    },
  },
})

"use client";

import { PopoverBasic as Example } from "@/components/rendyn-libraries/chakra/upstream/examples/popover-basic";
import { ChakraProvider, defaultSystem } from "@chakra-ui/react";

export default function Preview() {

  return <div style={{ width: "100%", maxWidth: "48rem", padding: "1.5rem" }}><ChakraProvider value={defaultSystem}><Example /></ChakraProvider></div>;
}

